import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  CircularProgress,
  EmptyState,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

type ProjectSpendPanelProps = {
  projects?: Project[];
  pageSize?: number;
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'archived'];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  archived: 'В архиве',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'neutral'> = {
  active: 'success',
  paused: 'warning',
  archived: 'neutral',
};

const DEFAULT_PROJECTS: Project[] = [
  { id: 'p-01', name: 'Атлас', used: 820, quota: 1000, status: 'active' },
  { id: 'p-02', name: 'Бореалис', used: 1180, quota: 1000, status: 'active' },
  { id: 'p-03', name: 'Кобальт', used: 310, quota: 1500, status: 'paused' },
  { id: 'p-04', name: 'Дельта-стрим', used: 640, quota: 800, status: 'active' },
  { id: 'p-05', name: 'Эхолот', used: 75, quota: 500, status: 'archived' },
  { id: 'p-06', name: 'Феррум', used: 450, quota: 600, status: 'paused' },
  { id: 'p-07', name: 'Гранит', used: 990, quota: 1000, status: 'active' },
  { id: 'p-08', name: 'Гелиос', used: 120, quota: 400, status: 'archived' },
  { id: 'p-09', name: 'Ирида', used: 260, quota: 900, status: 'active' },
  { id: 'p-10', name: 'Кварц', used: 700, quota: 750, status: 'paused' },
  { id: 'p-11', name: 'Лазурит', used: 40, quota: 300, status: 'archived' },
  { id: 'p-12', name: 'Меридиан', used: 530, quota: 1200, status: 'active' },
];

function usageTone(percent: number): 'success' | 'warning' | 'danger' {
  if (percent >= 90) return 'danger';
  if (percent >= 70) return 'warning';
  return 'success';
}

export default function ProjectSpendPanel({
  projects = DEFAULT_PROJECTS,
  pageSize = 5,
}: ProjectSpendPanelProps) {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [projects, activeStatuses],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <Card padding="lg">
      <Stack direction="column" gap="lg">
        <Stack direction="row" align="center" justify="between" gap="md" wrap>
          <Text as="h2" size="lg" weight="bold">
            Расход по проектам
          </Text>
          <Text size="sm" tone="muted">
            {filtered.length} из {projects.length}
          </Text>
        </Stack>

        <Stack direction="row" gap="sm" wrap role="group" aria-label="Фильтры по статусу">
          {STATUS_ORDER.filter((status) => activeStatuses.includes(status)).map((status) => (
            <Chip
              key={status}
              tone={STATUS_TONE[status]}
              dismissible
              onDismiss={() => removeStatus(status)}
              dismissLabel={`Снять фильтр «${STATUS_LABEL[status]}»`}
            >
              {STATUS_LABEL[status]} · {projects.filter((p) => p.status === status).length}
            </Chip>
          ))}
          {activeStatuses.length < STATUS_ORDER.length && (
            <Button variant="ghost" size="sm" onClick={resetFilters}>
              Сбросить фильтры
            </Button>
          )}
        </Stack>

        {visible.length === 0 ? (
          <EmptyState
            title="Проекты не найдены"
            description="Ни один статус не выбран. Верните фильтры, чтобы увидеть список проектов."
            action={
              <Button variant="primary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <Stack direction="column" gap="sm" as="ul" aria-label="Список проектов">
            {visible.map((project) => {
              const percent = project.quota > 0 ? Math.round((project.used / project.quota) * 100) : 0;
              return (
                <Stack
                  key={project.id}
                  as="li"
                  direction="row"
                  align="center"
                  justify="between"
                  gap="md"
                  style={{
                    padding: 'var(--jx-space-3) var(--jx-space-4)',
                    borderRadius: 'var(--jx-radius-md)',
                    background: 'var(--jx-color-surface-subtle)',
                  }}
                >
                  <Stack direction="row" align="center" gap="md" style={{ minWidth: 0 }}>
                    <CircularProgress
                      value={Math.min(percent, 100)}
                      max={100}
                      size="sm"
                      tone={usageTone(percent)}
                      showValue
                      aria-label={`Квота проекта «${project.name}» заполнена на ${percent} процентов`}
                    />
                    <Stack direction="column" gap="2xs" style={{ minWidth: 0 }}>
                      <Text weight="medium" truncate>
                        {project.name}
                      </Text>
                      <Text size="sm" tone="muted">
                        {project.used} из {project.quota} · {percent}%
                      </Text>
                    </Stack>
                  </Stack>
                  <Badge tone={STATUS_TONE[project.status]}>{STATUS_LABEL[project.status]}</Badge>
                </Stack>
              );
            })}
          </Stack>
        )}

        {visible.length > 0 && totalPages > 1 && (
          <Stack direction="row" justify="end">
            <Pagination page={currentPage} pageCount={totalPages} onPageChange={setPage} />
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

